custom_css:
/* ==========================================================
   SILLYTYPINGBAR + Y/N STYLE
   CLEAN VERSION
   iPhone / SillyTavern
   ========================================================== */

:root {
    --yn-bg: #000000;
    --yn-text: #f5f5f5;
    --yn-muted: #b7b7b7;

    --yn-tan: #c7a27c;
    --yn-green: #2ddd68;
    --yn-red: #ff1744;
    --yn-blue: #20a9ff;

    --stb-bg: #000000;
    --stb-border: rgba(104, 101, 42, 0.75);
    --stb-text: #a9a9a9;
    --stb-height: 52px;
}


/* ==========================================================
   GLOBAL
   ========================================================== */

html,
body,
#main,
#background,
#chat {
    background: #000000 !important;
    color: var(--yn-text) !important;
}

body,
#chat,
.mes,
.mes_text,
.mes .name_text,
#send_form {
    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "SF Pro Text",
        "SF Pro Display",
        "Helvetica Neue",
        Arial,
        sans-serif !important;
}


/* ==========================================================
   CHAT
   ========================================================== */

#chat {
    width: 100% !important;
    max-width: 100% !important;

    margin: 0 !important;

    padding:
        6px
        12px
        95px !important;

    box-sizing: border-box !important;

    overflow-x: hidden !important;
}


/* ==========================================================
   MESSAGES
   ========================================================== */

.mes {
    position: relative !important;

    display: block !important;

    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;

    margin: 0 !important;

    padding: 7px 0 13px !important;

    background: transparent !important;

    border: 0 !important;
    border-radius: 0 !important;

    box-shadow: none !important;

    box-sizing: border-box !important;
}


/* ==========================================================
   AVATAR
   ========================================================== */

.mes .mesAvatarWrapper {
    position: absolute !important;

    left: 0 !important;
    top: 7px !important;

    width: 58px !important;
    min-width: 58px !important;

    height: 48px !important;

    margin: 0 !important;
    padding: 0 !important;

    display: block !important;

    background: transparent !important;

    overflow: visible !important;

    z-index: 5 !important;
}


.mes .avatar,
.mes .avatar img {
    display: block !important;

    width: 48px !important;
    height: 48px !important;

    min-width: 48px !important;
    min-height: 48px !important;

    margin: 0 !important;
    padding: 0 !important;

    border: 0 !important;
    border-radius: 9px !important;

    object-fit: cover !important;

    background: #111 !important;

    box-shadow: none !important;
}


/* ==========================================================
   MESSAGE CONTENT
   ========================================================== */

.mes .mes_block {
    position: relative !important;

    display: block !important;

    width: calc(100% - 58px) !important;
    max-width: none !important;

    min-width: 0 !important;

    margin: 0 0 0 58px !important;

    padding:
        0
        0
        0
        9px !important;

    box-sizing: border-box !important;

    background: transparent !important;

    border: 0 !important;

    box-shadow: none !important;
}


/* ==========================================================
   CHARACTER COLOR BAR
   ========================================================== */

.mes .mes_block::before {
    content: "" !important;

    position: absolute !important;

    left: 0 !important;
    top: 0 !important;
    bottom: 0 !important;

    width: 3px !important;

    background: var(--yn-green) !important;

    border-radius: 0 !important;
}


/* ==========================================================
   GROUP CHARACTER COLORS
   ========================================================== */

.mes:nth-of-type(4n+1) .mes_block::before {
    background: var(--yn-tan) !important;
}

.mes:nth-of-type(4n+2) .mes_block::before {
    background: var(--yn-green) !important;
}

.mes:nth-of-type(4n+3) .mes_block::before {
    background: var(--yn-red) !important;
}

.mes:nth-of-type(4n) .mes_block::before {
    background: var(--yn-blue) !important;
}


/* ==========================================================
   CHARACTER NAME
   ========================================================== */

.mes .ch_name {
    display: block !important;

    width: 100% !important;

    margin: 0 0 3px !important;
    padding: 0 !important;

    background: transparent !important;

    border: 0 !important;
}


.mes .ch_name > .flex-container {
    display: flex !important;

    align-items: center !important;

    gap: 6px !important;

    flex-wrap: nowrap !important;
}


.mes .ch_name .name_text {
    display: inline-block !important;

    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "SF Pro Display",
        "SF Pro Text",
        "Helvetica Neue",
        Arial,
        sans-serif !important;

    font-size: 16px !important;

    line-height: 1.15 !important;

    font-weight: 700 !important;

    white-space: nowrap !important;

    color: #ffffff !important;
}


/* ==========================================================
   CHARACTER NAME COLORS
   ========================================================== */

.mes:nth-of-type(4n+1) .name_text {
    color: var(--yn-tan) !important;
}

.mes:nth-of-type(4n+2) .name_text {
    color: var(--yn-green) !important;
}

.mes:nth-of-type(4n+3) .name_text {
    color: var(--yn-red) !important;
}

.mes:nth-of-type(4n) .name_text {
    color: var(--yn-blue) !important;
}


/* Specific names */

.mes .name_text[title*="Adolf"],
.mes .name_text[title*="Hitler"] {
    color: var(--yn-green) !important;
}

.mes .name_text[title*="Himmler"] {
    color: var(--yn-red) !important;
}

.mes .name_text[title*="Jojo"],
.mes .name_text[title*="Betzler"] {
    color: var(--yn-tan) !important;
}

.mes .name_text[title*="Goebbels"] {
    color: var(--yn-tan) !important;
}


/* ==========================================================
   MESSAGE TEXT
   ========================================================== */

.mes .mes_text {
    display: block !important;

    width: 100% !important;
    max-width: 100% !important;

    min-width: 0 !important;

    margin: 0 !important;
    padding: 0 !important;

    background: transparent !important;

    color: var(--yn-text) !important;

    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "SF Pro Text",
        "SF Pro Display",
        "Helvetica Neue",
        Arial,
        sans-serif !important;

    font-size: 15px !important;

    line-height: 1.42 !important;

    font-weight: 500 !important;

    overflow-wrap: normal !important;
    word-break: normal !important;

    white-space: normal !important;
}


.mes .mes_text p {
    display: block !important;

    margin: 0 0 7px !important;
    padding: 0 !important;
}


.mes .mes_text p:last-child {
    margin-bottom: 0 !important;
}


/* ==========================================================
   ITALICS / ACTIONS
   ========================================================== */

.mes .mes_text em,
.mes .mes_text i {
    color: #b8b8b8 !important;

    font-style: italic !important;

    font-weight: 600 !important;
}


/* ==========================================================
   DIALOGUE
   ========================================================== */

.mes .mes_text strong,
.mes .mes_text b {
    color: #f5f5f5 !important;

    font-weight: 700 !important;
}


/* ==========================================================
   REMOVE CARD / QUOTE STYLE
   ========================================================== */

.mes .mes_text blockquote,
.mes .mes_text pre,
.mes .mes_text code {
    background: transparent !important;

    border: 0 !important;

    box-shadow: none !important;
}


/* ==========================================================
   MESSAGE METADATA
   ========================================================== */

.mes .mes_timer,
.mes .mesIDDisplay {
    display: none !important;
}


/* ==========================================================
   MESSAGE BUTTONS
   ========================================================== */

.mes .mes_buttons {
    opacity: 0 !important;

    transition: opacity 0.15s ease;
}

.mes:hover .mes_buttons {
    opacity: 1 !important;
}


/* ==========================================================
   TYPING INDICATOR
   ========================================================== */

#typing_indicator,
.typing_indicator,
#typing-indicator,
.typing-indicator {
    background: transparent !important;

    border: 0 !important;

    box-shadow: none !important;

    color: #aaa !important;

    margin: 0 !important;

    padding:
        0
        0
        7px
        58px !important;

    font-size: 15px !important;

    font-weight: 600 !important;

    line-height: 1.25 !important;
}


/* ==========================================================
   🌗 LIGHT / DARK MODE — DRACO IS TYPING
   ========================================================== */

:root {
    --draco-bg: #000000;
    --draco-bg-2: #111111;
    --draco-text: #f5f5f5;
    --draco-muted: #b9b9b9;
    --draco-border: #252525;
    --draco-input: #111111;
    --draco-avatar-bg: #111111;
}

/* ☀️ MODE CLAIR */
body.light-mode,
html.light-mode,
body[data-theme="light"],
html[data-theme="light"] {
    --draco-bg: #f5f5f7;
    --draco-bg-2: #ffffff;
    --draco-text: #111111;
    --draco-muted: #666666;
    --draco-border: #d5d5da;
    --draco-input: #ffffff;
    --draco-avatar-bg: #e5e5ea;
    color-scheme: light;
}

/* 🌑 MODE SOMBRE */
body.dark-mode,
html.dark-mode,
body[data-theme="dark"],
html[data-theme="dark"] {
    --draco-bg: #000000;
    --draco-bg-2: #111111;
    --draco-text: #f5f5f5;
    --draco-muted: #b9b9b9;
    --draco-border: #252525;
    --draco-input: #111111;
    --draco-avatar-bg: #111111;
    color-scheme: dark;
}

/* FONDS */
html,
body,
#main,
#background,
#sheld,
#chat {
    background: var(--draco-bg) !important;
    color: var(--draco-text) !important;
}

/* MESSAGES */
.mes,
.mes .mes_block,
.mes .mes_text,
.mes .ch_name {
    background: transparent !important;
    color: var(--draco-text) !important;
}

.mes .mes_text {
    color: var(--draco-text) !important;
}

.mes .mes_text em,
.mes .mes_text i {
    color: var(--draco-muted) !important;
}

.mes .mes_text strong,
.mes .mes_text b {
    color: var(--draco-text) !important;
}

/* AVATARS */
.mes .avatar,
.mes .avatar img {
    background: var(--draco-avatar-bg) !important;
}

/* BARRE DE FRAPPE */
#form_sheld {
    background: var(--draco-bg) !important;
    border-color: var(--draco-border) !important;
}

#send_form {
    background: var(--draco-input) !important;
    border-color: var(--draco-border) !important;
    color: var(--draco-text) !important;
}

#send_textarea {
    background: var(--draco-input) !important;
    color: var(--draco-text) !important;
    border-color: var(--draco-border) !important;
}

#send_textarea::placeholder {
    color: var(--draco-muted) !important;
}

/* INTERFACE */
button,
.menu_button,
input,
textarea,
select {
    color: var(--draco-text);
    border-color: var(--draco-border);
}

/* MENUS / POPUPS */
.popup,
.menu,
.dropdown-menu,
#contextMenu,
.drawer-content {
    background: var(--draco-bg-2) !important;
    color: var(--draco-text) !important;
    border-color: var(--draco-border) !important;
}

/* SCROLLBAR */
* {
    scrollbar-color: var(--draco-border) var(--draco-bg);
}

/* TRANSITION */
html,
body,
#sheld,
#chat,
#form_sheld,
#send_form,
#send_textarea,
.popup,
.menu,
button {
    transition:
        background-color .18s ease,
        color .18s ease,
        border-color .18s ease !important;
}

/* ==========================================================
   RÉGLAGES (variables) + BARRE DE SAISIE
   ========================================================== */
/* ===== Variables par défaut (modifiées par le panneau) ===== */
:root{
  --yn-bot-text:#f5f5f5; --yn-bot-italic:#b8b8b8; --yn-bot-size:15px;
  --yn-user-text:#f5f5f5; --yn-user-italic:#b8b8b8; --yn-user-size:15px;
  --yn-line-height:1.42;
  --yn-bar-bg:#000000; --yn-icon:#b4b4b9; --yn-input-text:#f5f5f5; --yn-placeholder:#8e8e93; --yn-send:#1e90ff;
}

/* ===== Texte des messages ===== */
.mes[is_user="false"] .mes_text{color:var(--yn-bot-text)!important;font-size:var(--yn-bot-size)!important;line-height:var(--yn-line-height)!important;}
.mes[is_user="false"] .mes_text em,.mes[is_user="false"] .mes_text i{color:var(--yn-bot-italic)!important;}
.mes[is_user="false"] .mes_text strong,.mes[is_user="false"] .mes_text b,.mes[is_user="false"] .mes_text q{color:var(--yn-bot-text)!important;}
.mes[is_user="true"] .mes_text{color:var(--yn-user-text)!important;font-size:var(--yn-user-size)!important;line-height:var(--yn-line-height)!important;}
.mes[is_user="true"] .mes_text em,.mes[is_user="true"] .mes_text i{color:var(--yn-user-italic)!important;}
.mes[is_user="true"] .mes_text strong,.mes[is_user="true"] .mes_text b,.mes[is_user="true"] .mes_text q{color:var(--yn-user-text)!important;}

/* ===== Barre de saisie ===== */
#form_sheld{position:fixed!important;left:0!important;right:0!important;bottom:0!important;top:auto!important;width:100%!important;max-width:100%!important;
  margin:0!important;padding-bottom:env(safe-area-inset-bottom)!important;z-index:30!important;transform:none!important;}
#leftSendForm .displayNone,#rightSendForm .displayNone,#mes_stop.displayNone,#mes_impersonate.displayNone{display:none!important;}
#sheld{height:100dvh!important;}
#chat{padding-bottom:110px!important;}
#form_sheld{background:var(--yn-bar-bg)!important;border:0!important;box-shadow:none!important;}
#send_form{background:var(--yn-bar-bg)!important;border:0!important;border-radius:0!important;box-shadow:none!important;padding:6px 8px!important;outline:0!important;}
#nonQRFormItems{display:flex!important;flex-direction:row!important;flex-wrap:nowrap!important;width:100%!important;align-items:center!important;gap:4px!important;background:transparent!important;border:0!important;}
#leftSendForm,#rightSendForm{display:flex!important;flex-direction:row!important;flex-wrap:nowrap!important;align-items:center!important;gap:2px!important;flex:0 0 auto!important;background:transparent!important;}
#send_textarea{flex:1 1 auto!important;min-width:0!important;background:transparent!important;border:0!important;box-shadow:none!important;outline:0!important;
  color:var(--yn-input-text)!important;font-size:16px!important;min-height:38px!important;padding:8px 6px!important;}
#send_textarea::placeholder{color:var(--yn-placeholder)!important;opacity:1!important;}
#send_form .fa-solid,#send_form .fa-regular,#send_form .fa-fw,#send_form .interactable{color:var(--yn-icon)!important;}
#leftSendForm>div:not(.displayNone),#rightSendForm>div:not(.displayNone){width:36px!important;height:36px!important;display:flex!important;align-items:center!important;justify-content:center!important;
  font-size:19px!important;margin:0!important;background:transparent!important;border:0!important;}
#mes_continue{display:none!important;}
#send_but{background:var(--yn-send)!important;border-radius:50%!important;width:40px!important;height:40px!important;margin-left:4px!important;}
#send_but,#send_but::before{color:#fff!important;}

/* Boutons ajoutés */
.yn-bar-btn{position:relative;width:36px;height:36px;display:flex;align-items:center;justify-content:center;
  color:var(--yn-icon);font-size:19px;cursor:pointer;flex:0 0 auto;-webkit-tap-highlight-color:transparent;}
.yn-bar-btn img{width:28px;height:28px;border-radius:50%;object-fit:cover;filter:grayscale(1);}
.yn-bar-btn.yn-caret::after{content:"";position:absolute;top:3px;right:2px;border-left:4px solid transparent;border-right:4px solid transparent;border-bottom:6px solid #fff;}
